const crypto = require('crypto');
const item = items[0].json;
const sigHeader = item.headers?.['x-webwelle-signature'] || item.headers?.['X-Webwelle-Signature'];
const secret = item._webwelleN8nWebhookSecret || 'dev-n8n-secret';
let raw = typeof item.rawBody === 'string' ? item.rawBody : '';
if (!raw && item.body !== undefined) {
  raw = typeof item.body === 'string' ? item.body : JSON.stringify(item.body);
}
if (!raw) raw = '{}';
const candidateStrings = new Set([raw]);
if (item.body && typeof item.body === 'object') {
  candidateStrings.add(JSON.stringify(item.body));
  const keys = Object.keys(item.body).sort();
  const sorted = {};
  for (const k of keys) sorted[k] = item.body[k];
  candidateStrings.add(JSON.stringify(sorted));
}
let verified = false;
for (const s of candidateStrings) {
  const expectedHex = crypto.createHmac('sha256', secret).update(s).digest('hex');
  if (sigHeader && sigHeader === expectedHex) {
    verified = true;
    break;
  }
}
if (!verified) {
  throw new Error('Ungueltige oder fehlende x-webwelle-signature');
}
let body;
try {
  body = JSON.parse(raw);
} catch {
  body = item.body && typeof item.body === 'object' ? item.body : {};
}
const leadId = body.leadId || '';
const token = body.token || '';
const industry = (body.industry || 'Dienstleister').trim();
const postalCode = (body.postalCode || '').trim();
const market = (body.market || 'DE').trim();
const callbackBaseUrl = String(body.callbackBaseUrl || '').replace(/\\/$/, '');
if (!leadId) throw new Error('leadId fehlt');

const existingWebsite = body.existingWebsite === true;
const existingWebsiteUrl = String(body.existingWebsiteUrl || '').trim();
const isOwnSiteSupplement = body.isOwnSiteSupplement === true;

function normalizeOwnSite(c, fallbackName) {
  const source = c && typeof c === 'object' ? c : {};
  const websiteUrl = String(source.websiteUrl || source.url || existingWebsiteUrl || '').trim();
  if (!websiteUrl) return null;
  let domain = String(source.domain || '').trim().toLowerCase().replace(/^www\\./, '');
  if (!domain) {
    try {
      const u = /^https?:\\/\\//i.test(websiteUrl) ? websiteUrl : 'https://' + websiteUrl;
      domain = new URL(u).hostname.replace(/^www\\./, '').toLowerCase();
    } catch {
      return null;
    }
  }
  const normalizedUrl = /^https?:\\/\\//i.test(websiteUrl) ? websiteUrl : 'https://' + websiteUrl;
  return {
    name: String(source.name || fallbackName || domain).slice(0, 200),
    domain,
    websiteUrl: normalizedUrl,
    isOwnSite: true,
  };
}

let ownSite = normalizeOwnSite(body.ownSite, 'Ihre Website');
if (!ownSite && existingWebsite && existingWebsiteUrl) {
  ownSite = normalizeOwnSite({ websiteUrl: existingWebsiteUrl, name: 'Ihre Website' }, 'Ihre Website');
}

if (!isOwnSiteSupplement && !postalCode) throw new Error('postalCode fehlt');
if (isOwnSiteSupplement && !ownSite) throw new Error('ownSite fehlt fuer Own-Site-Supplement');

return [{
  json: {
    leadId,
    token,
    industry,
    postalCode,
    market,
    callbackBaseUrl,
    existingWebsite,
    existingWebsiteUrl,
    ownSite,
    isOwnSiteSupplement,
  },
}];

const lead = $('Normalize And Verify HMAC').first().json;
const geo = items[0].json;
const results = geo.results || [];
if (!results.length) {
  return [{
    json: {
      ...lead,
      lat: null,
      lng: null,
      locality: '',
      formattedAddress: '',
      geocodeError: 'empty',
    },
  }];
}
const loc = results[0].geometry?.location || {};
const comps = results[0].address_components || [];
const locality =
  (comps.find((c) => c.types?.includes('locality')) || {}).long_name ||
  (comps.find((c) => c.types?.includes('postal_town')) || {}).long_name ||
  (comps.find((c) => c.types?.includes('sublocality')) || {}).long_name ||
  '';
return [{
  json: {
    ...lead,
    lat: loc.lat,
    lng: loc.lng,
    locality,
    formattedAddress: results[0].formatted_address || '',
  },
}];

/**
 * n8n Code-Node: Ersatz fuer HTTP „Places Text Search“.
 * Reihenfolge: Places API (New) → Places API (Legacy + Details) → CSE (nur wenn Engine Web-Suche erlaubt).
 */
const pg = items[0].json;
const inj = $('Inject Webwelle Env').first().json;
const httpRequest = this.helpers.httpRequest.bind(this.helpers);
const mapsKey = inj._googleMapsApiKey || '';
const cseKey = inj._googleCseApiKey || '';
const cseId = inj._googleCseId || '';

const textQuery = `${pg.industry || ''} ${pg.postalCode || ''} ${pg.locality || ''}`.trim();
const locationBias =
  pg.lat != null && pg.lng != null
    ? { circle: { center: { latitude: pg.lat, longitude: pg.lng }, radius: 20000 } }
    : undefined;

let places = [];
let discoverSource = 'none';

/** Places API (New) — benoetigt „Places API (New)“ in GCP */
if (mapsKey && textQuery && !places.length) {
  try {
    const body = { textQuery };
    if (locationBias) body.locationBias = locationBias;
    const res = await httpRequest({
      method: 'POST',
      url: 'https://places.googleapis.com/v1/places:searchText',
      headers: {
        'X-Goog-Api-Key': mapsKey,
        'X-Goog-FieldMask':
          'places.displayName,places.formattedAddress,places.websiteUri,places.googleMapsUri,places.location',
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
      timeout: 20000,
      json: true,
      ignoreResponseCode: true,
    });
    if (res && Array.isArray(res.places) && res.places.length) {
      places = res.places;
      discoverSource = 'places_new';
    }
  } catch {
    /* weiter */
  }
}

/** Places API (Legacy) Text Search + Details — benoetigt „Places API“ (klassisch) in GCP */
if (mapsKey && textQuery && !places.length) {
  try {
    let url =
      'https://maps.googleapis.com/maps/api/place/textsearch/json?query=' +
      encodeURIComponent(textQuery) +
      '&key=' +
      encodeURIComponent(mapsKey);
    if (pg.lat != null && pg.lng != null) {
      url += '&location=' + encodeURIComponent(`${pg.lat},${pg.lng}`) + '&radius=20000';
    }
    const data = await httpRequest({ method: 'GET', url, timeout: 20000, json: true, ignoreResponseCode: true });
    const status = data?.status || '';
    if (status === 'OK' || status === 'ZERO_RESULTS') {
      const legacyPlaces = [];
      for (const r of (data.results || []).slice(0, 10)) {
        if (!r.place_id) continue;
        let website = '';
        let mapsUrl = '';
        let formatted = r.formatted_address || '';
        try {
          const detUrl =
            'https://maps.googleapis.com/maps/api/place/details/json?place_id=' +
            encodeURIComponent(r.place_id) +
            '&fields=name,website,formatted_address,url&key=' +
            encodeURIComponent(mapsKey);
          const det = await httpRequest({ method: 'GET', url: detUrl, timeout: 12000, json: true, ignoreResponseCode: true });
          if (det?.status === 'OK' && det.result) {
            website = det.result.website || '';
            mapsUrl = det.result.url || '';
            formatted = det.result.formatted_address || formatted;
          }
        } catch {
          /* skip details */
        }
        if (!website) continue;
        legacyPlaces.push({
          displayName: { text: r.name || '' },
          formattedAddress: formatted,
          websiteUri: website,
          googleMapsUri: mapsUrl,
        });
      }
      if (legacyPlaces.length) {
        places = legacyPlaces;
        discoverSource = 'places_legacy';
      }
    }
  } catch {
    /* weiter */
  }
}

/** CSE — nur sinnvoll bei Engine mit echter Web-Suche (neue Engines oft nur bis 50 Domains) */
if (!places.length && cseKey && cseId && textQuery) {
  const country =
    pg.market === 'CH' ? 'Schweiz' : pg.market === 'AT' ? 'Oesterreich' : 'Deutschland';
  const q = `${pg.industry} ${pg.postalCode} ${pg.locality || ''} ${country}`.trim();
  try {
    const url =
      'https://www.googleapis.com/customsearch/v1?key=' +
      encodeURIComponent(cseKey) +
      '&cx=' +
      encodeURIComponent(cseId) +
      '&q=' +
      encodeURIComponent(q) +
      '&num=10';
    const cse = await httpRequest({ method: 'GET', url, timeout: 15000, json: true, ignoreResponseCode: true });
    const itemsList = cse?.items || [];
    places = itemsList
      .map((it) => {
        const link = it.link || '';
        if (!link || !/^https?:\/\//i.test(link)) return null;
        const title = (it.title || '').replace(/\s*[-|–|—].*$/, '').trim().slice(0, 200);
        return {
          displayName: { text: title || link },
          formattedAddress: pg.formattedAddress || String(pg.postalCode || ''),
          websiteUri: link,
          googleMapsUri: '',
        };
      })
      .filter(Boolean);
    if (places.length) discoverSource = 'cse';
  } catch {
    /* leer */
  }
}

return [{ json: { places, discoverSource } }];

/**
 * n8n Code-Node: Places/CSE-Rohdaten → deduplizierte Wettbewerber-Liste.
 * Robust gegen fehlendes URL-Global (Task-Runner), mehrere Input-Items und Feldvarianten.
 */
const pg = $('Parse Geocode').first().json;
const placesRes = items[0]?.json || {};

function asPlaceList(source, allItems) {
  if (Array.isArray(source.places) && source.places.length) return source.places;
  if (allItems.length > 1) {
    return allItems
      .map((it) => it.json)
      .filter((j) => j && (j.websiteUri || j.website || j.displayName || j.formattedAddress));
  }
  if (source.websiteUri || source.website || source.displayName || source.formattedAddress) {
    return [source];
  }
  return [];
}

const places = asPlaceList(placesRes, items);
const discoverSource = placesRes.discoverSource || 'none';

function websiteOf(p) {
  const raw = p.websiteUri ?? p.website ?? p.url ?? '';
  if (typeof raw === 'string') return raw.trim();
  if (raw && typeof raw === 'object') {
    if (typeof raw.uri === 'string') return raw.uri.trim();
    if (typeof raw.value === 'string') return raw.value.trim();
  }
  return '';
}

function nameOf(p) {
  const dn = p.displayName;
  if (dn && typeof dn === 'object' && typeof dn.text === 'string') return dn.text;
  if (typeof dn === 'string') return dn;
  return p.name || p.title || '';
}

function domainFromUrl(u) {
  const s = String(u || '').trim();
  if (!s) return '';
  try {
    if (typeof URL !== 'undefined') {
      const url = /^https?:\/\//i.test(s) ? s : `https://${s}`;
      return new URL(url).hostname.replace(/^www\./i, '').toLowerCase();
    }
  } catch {
    /* regex fallback */
  }
  const m =
    s.match(/^https?:\/\/([^/?#]+)/i) ||
    s.match(/^www\.([^/?#]+)/i) ||
    s.match(/^([a-z0-9][-a-z0-9]*(?:\.[a-z0-9][-a-z0-9]*)+)/i);
  if (!m) return '';
  return m[1].replace(/^www\./i, '').toLowerCase();
}

function normalizeUrl(u) {
  const s = String(u || '').trim();
  if (!s) return '';
  try {
    if (typeof URL !== 'undefined') {
      const url = /^https?:\/\//i.test(s) ? s : `https://${s}`;
      const parsed = new URL(url);
      const path = parsed.pathname.replace(/\/$/, '');
      return parsed.origin + path || url;
    }
  } catch {
    /* fall through */
  }
  return /^https?:\/\//i.test(s) ? s : `https://${s}`;
}

function isBlockedDomain(dom) {
  const d = dom.toLowerCase();
  return /(^|\.)google\.|(^|\.)gstatic\.|(^|\.)facebook\.|(^|\.)fbcdn\.|(^|\.)instagram\.|(^|\.)linkedin\.|(^|\.)youtube\.|(^|\.)youtu\.be$|gelbeseiten|11880|dasoertliche|kennst-du-einen|(^|\.)wikipedia\.|(^|\.)amazon\.|(^|\.)ebay\.|(^|\.)yelp\./i.test(
    d,
  );
}

const competitors = [];
for (const p of places) {
  const w = websiteOf(p);
  if (!w) continue;
  const dom = domainFromUrl(w);
  if (!dom || isBlockedDomain(dom)) continue;
  const name = nameOf(p) || dom;
  competitors.push({
    name: String(name).slice(0, 200),
    domain: dom,
    websiteUrl: normalizeUrl(w),
    mapsUri: p.googleMapsUri || p.url || '',
    address: p.formattedAddress || '',
  });
}

const cseUsed = discoverSource === 'cse';

const uniq = [];
const seen = new Set();
for (const c of competitors) {
  if (seen.has(c.domain)) continue;
  seen.add(c.domain);
  uniq.push(c);
}
let top = uniq.slice(0, 10);

let norm = {};
try {
  norm = $('Normalize And Verify HMAC').first().json || {};
} catch {
  norm = {};
}
if (norm.ownSite && norm.ownSite.websiteUrl && !norm.isOwnSiteSupplement) {
  const own = { ...norm.ownSite, isOwnSite: true, name: norm.ownSite.name || 'Ihre Website' };
  const filtered = top.filter((c) => c.domain !== own.domain);
  top = [own, ...filtered].slice(0, 5);
}


return [
  {
    json: {
      leadId: pg.leadId,
      token: pg.token,
      industry: pg.industry,
      postalCode: pg.postalCode,
      market: pg.market,
      locality: pg.locality,
      lat: pg.lat,
      lng: pg.lng,
      formattedAddress: pg.formattedAddress,
      competitors: top,
      discoverMeta: {
        placesCount: places.length,
        cseUsed,
        picked: top.length,
        source: discoverSource,
      },
    },
  },
];

const row = items[0].json;
const list = (row.competitors || []).slice(0, 5);
const httpRequest = this.helpers.httpRequest.bind(this.helpers);

function normalizeHex(h) {
  let x = String(h).toLowerCase();
  if (!x.startsWith('#')) x = '#' + x;
  if (x.length === 4) {
    const r = x[1];
    const g = x[2];
    const b = x[3];
    x = '#' + r + r + g + g + b + b;
  }
  return x.length === 7 ? x : null;
}

function isMutedColor(hex) {
  if (!hex) return true;
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  if (r > 245 && g > 245 && b > 245) return true;
  if (r < 12 && g < 12 && b < 12) return true;
  return false;
}

function extractColors(html) {
  const set = new Set();
  const raw = String(html || '');
  const hexMatches = raw.match(/#([0-9a-fA-F]{3,8})\b/g) || [];
  for (const h of hexMatches) {
    const n = normalizeHex(h);
    if (n && !isMutedColor(n)) set.add(n);
  }
  const rgbMatches = raw.match(/rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/gi) || [];
  for (const rgb of rgbMatches.slice(0, 20)) {
    const m = rgb.match(/(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/);
    if (!m) continue;
    const hex =
      '#' +
      [m[1], m[2], m[3]]
        .map((n) => Math.min(255, parseInt(n, 10)).toString(16).padStart(2, '0'))
        .join('');
    if (!isMutedColor(hex)) set.add(hex);
  }
  return [...set].slice(0, 5);
}

function extractLayout(html) {
  const h = String(html || '');
  const low = h.toLowerCase();
  const hints = [];
  if (/<header[\s>]/i.test(h) || /class=["'][^"']*hero|id=["']hero/i.test(h)) hints.push('Hero-Bereich');
  if (/<nav[\s>]/i.test(h) || /class=["'][^"']*nav/i.test(low)) hints.push('Navigation');
  if (/<footer[\s>]/i.test(h)) hints.push('Footer');
  if (/sticky|position:\s*fixed/i.test(low)) hints.push('Fixierte Kopfzeile');
  if (/<section/i.test(h)) hints.push('Sektionen');
  if (/<main[\s>]/i.test(h)) hints.push('Main-Content');
  return [...new Set(hints)];
}

function extractMotion(html) {
  const low = String(html || '').toLowerCase();
  const m = [];
  if (low.includes('data-aos') || low.includes('aos.css')) m.push('AOS Scroll-Effekte');
  if (low.includes('gsap')) m.push('GSAP Animation');
  if (low.includes('scroll-behavior') || low.includes('lenis')) m.push('Smooth Scroll');
  if (low.includes('swiper') || low.includes('slick')) m.push('Slider/Karussell');
  if (low.includes('@keyframes')) m.push('CSS-Keyframes');
  if (low.includes('framer-motion') || low.includes('framer-motion')) m.push('Framer Motion');
  if (low.includes('wow.js') || low.includes('animate.css')) m.push('Scroll-Animationen');
  return [...new Set(m)];
}

function extractFonts(html) {
  const fonts = new Set();
  const ff = String(html || '').match(/font-family:\s*([^;}"']+)/gi) || [];
  for (const f of ff) {
    const name = f.replace(/font-family:\s*/i, '').split(',')[0].replace(/['"]/g, '').trim();
    if (name && name.length < 40) fonts.add(name);
  }
  const google = String(html || '').match(/fonts\.googleapis\.com\/css2?\?family=([^"'&]+)/i);
  if (google) {
    decodeURIComponent(google[1])
      .split('|')
      .forEach((g) => fonts.add(g.replace(/\+/g, ' ').split(':')[0]));
  }
  return [...fonts].slice(0, 5);
}

function blockSnippet(html) {
  if (!html || typeof html !== 'string') return { title: '', snippet: '' };
  const t = html.match(/<title[^>]*>([^<]*)<\/title>/i);
  const title = t ? t[1].replace(/\s+/g, ' ').trim().slice(0, 200) : '';
  const stripped = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  return { title, snippet: stripped.slice(0, 3500) };
}

const evidence = [];
for (const c of list) {
  let html = '';
  try {
    html = await httpRequest({
      method: 'GET',
      url: c.websiteUrl,
      timeout: 10000,
      headers: {
        'User-Agent': 'Mozilla/5.0 (compatible; WebwelleResearch/1.0)',
        Accept: 'text/html,application/xhtml+xml',
        'Accept-Language': 'de-DE,de;q=0.9',
      },
      ignoreResponseCode: true,
      json: false,
    });
    if (typeof html !== 'string') html = JSON.stringify(html);
  } catch {
    html = '';
  }
  const meta = blockSnippet(html);
  const colors = extractColors(html);
  const layoutHints = extractLayout(html);
  const motionHints = extractMotion(html);
  const fonts = extractFonts(html);
  evidence.push({
    name: c.name,
    domain: c.domain,
    websiteUrl: c.websiteUrl,
    mapsUri: c.mapsUri || '',
    address: c.address || '',
    title: meta.title,
    textSnippet: meta.snippet,
    colors,
    layoutHints,
    motionHints,
    fonts,
    screenshotUrl: null,
  });
}

return [{ json: { ...row, evidence } }];

const row = items[0].json;
const evidence = row.evidence || [];
const model = $('Inject Webwelle Env').first().json._openrouterModel || 'google/gemma-2-9b-it:free';

const schemaHint = `Antworte NUR mit einem JSON-Objekt (kein Markdown) in exakt dieser Struktur:
{
  "competitors": [
    {
      "name": string,
      "domain": string,
      "websiteUrl": string,
      "screenshotUrl": string|null,
      "palette": string[],
      "layoutPattern": string,
      "typography": string,
      "designScore": number,
      "strengths": string[],
      "weaknesses": string[],
      "designAge": "modern"|"dated"|"mixed",
      "subPages": [{"url":string,"category":string}],
      "functions": string[]
    }
  ],
  "summary": string,
  "recommendation": string
}
Nutze nur die gelieferten URLs; keine erfundenen Domains. Wenn Daten fehlen, schwache Felder leer lassen und in weaknesses erklaeren.`;

const user = JSON.stringify(
  {
    kontext: {
      industry: row.industry,
      postalCode: row.postalCode,
      market: row.market,
      locality: row.locality,
      formattedAddress: row.formattedAddress,
      discoverMeta: row.discoverMeta,
    },
    konkurrentenEvidenz: evidence,
  },
  null,
  2,
);

const openRouterBody = {
  model,
  temperature: 0.35,
  stream: false,
  messages: [
    {
      role: 'system',
      content:
        'Du bist Senior UX-/Webdesign-Analyst fuer lokale KMU-Websites im DACH-Raum. ' + schemaHint,
    },
    { role: 'user', content: user },
  ],
};

return [{ json: { ...row, openRouterBody, skipLlm: evidence.length === 0 } }];

const row = $('Build OpenRouter Body').first().json;
const emptyPayload = {
  leadId: row.leadId,
  competitors: [],
  summary:
    'Fuer ' +
    row.industry +
    ' in PLZ ' +
    row.postalCode +
    ' wurden keine geeigneten Konkurrenten-Websites mit oeffentlicher Domain gefunden (Places/CSE). Bitte PLZ pruefen oder spaeter erneut versuchen.',
  recommendation:
    'Ohne lokale Referenzseiten: Fokus auf klares eigenes Layout (Hero, Leistungen, regionale Vertrauenssignale, starke CTA) und manuelle 2–3 Wettbewerber-URLs ergaenzen.',
  done: true,
};
return [{ json: { ...row, parsed: emptyPayload } }];

const orRes = items[0].json;
const row = $('Build OpenRouter Body').first().json;
let text = '';
try {
  text = orRes.choices?.[0]?.message?.content || '';
} catch (e) {
  text = '';
}

function extractJson(s) {
  if (!s) return null;
  const t = s.trim();
  const fence = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fence ? fence[1].trim() : t;
  try {
    return JSON.parse(candidate);
  } catch {
    const start = candidate.indexOf('{');
    const end = candidate.lastIndexOf('}');
    if (start >= 0 && end > start) {
      try {
        return JSON.parse(candidate.slice(start, end + 1));
      } catch {
        return null;
      }
    }
    return null;
  }
}

const parsed = extractJson(text);
const evidence = row.evidence || [];

function normalizeComp(c, idx) {
  const ev = evidence[idx] || evidence.find((e) => e.domain === c.domain) || {};
  const url = c.websiteUrl || ev.websiteUrl || '';
  let domain = c.domain || ev.domain || '';
  if (!domain && url) {
    try {
      domain = new URL(url.startsWith('http') ? url : 'https://' + url).hostname.replace(/^www\./, '');
    } catch {
      domain = '';
    }
  }
  return {
    subPages: Array.isArray(c.subPages) ? c.subPages.slice(0, 40) : [],
    functions: Array.isArray(c.functions) ? c.functions : [],
    name: c.name || ev.name || domain || 'Unbekannt',
    domain,
    websiteUrl: url,
    screenshotUrl: c.screenshotUrl ?? ev.screenshotUrl ?? null,
    palette: Array.isArray(c.palette) ? c.palette.slice(0, 5) : [],
    layoutPattern: c.layoutPattern || '',
    typography: c.typography || '',
    designScore: typeof c.designScore === 'number' ? Math.min(10, Math.max(0, c.designScore)) : 0,
    strengths: Array.isArray(c.strengths) ? c.strengths : [],
