function formatErr(e) {
  if (e == null) return 'Unbekannter Fehler';
  if (typeof e === 'string') return e;
  if (e instanceof Error) return e.message || 'Unbekannter Fehler';
  if (typeof e === 'object') {
    const o = e;
    if (typeof o.message === 'string' && o.message) return o.message;
    if (o.error && typeof o.error.message === 'string') return o.error.message;
    try {
      return JSON.stringify(e).slice(0, 280);
    } catch {
      return 'Unbekannter Fehler';
    }
  }
  return String(e);
}

function openRouterModels(preferred) {
  const list = [
    preferred,
    'google/gemini-2.0-flash-001',
    'meta-llama/llama-3.1-8b-instruct:free',
    'openai/gpt-4o-mini',
  ].filter(Boolean);
  const seen = new Set();
  return list.filter((m) => {
    if (seen.has(m)) return false;
    seen.add(m);
    return true;
  });
}

async function openRouterChat(httpRequest, opts) {
  const { apiKey, referer, title, body, formatErr: fe } = opts;
  if (!apiKey) throw new Error('OPENROUTER_API_KEY fehlt in n8n');
  const models = openRouterModels(body.model);
  let lastErr = null;
  for (const model of models) {
    try {
      const res = await httpRequest({
        method: 'POST',
        url: 'https://openrouter.ai/api/v1/chat/completions',
        headers: {
          Authorization: 'Bearer ' + apiKey,
          'HTTP-Referer': referer,
          'X-Title': title,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ ...body, model }),
        timeout: opts.timeout || 50000,
        json: true,
        ignoreResponseCode: true,
      });
      if (res?.error) {
        const msg = res.error.message || JSON.stringify(res.error);
        if (/404|not found|no endpoints/i.test(String(msg))) {
          lastErr = new Error(msg);
          continue;
        }
        throw new Error(msg);
      }
      if (res?.choices?.length) return res;
      lastErr = new Error('Leere OpenRouter-Antwort');
    } catch (e) {
      lastErr = e;
      if (/404|not found|no endpoints/i.test(fe(e))) continue;
      throw e;
    }
  }
  throw lastErr || new Error('Kein OpenRouter-Modell verfügbar');
}

function extractJson(s) {
  if (!s) return null;
  const t = s.trim();
  const fence = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fence ? fence[1].trim() : t;
  try {
    return JSON.parse(candidate);
  } catch {
    const start = candidate.indexOf('{');
    const end = candidate.lastIndexOf('}');
    if (start >= 0 && end > start) {
      try {
        return JSON.parse(candidate.slice(start, end + 1));
      } catch {
        return null;
      }
    }
    return null;
  }
}

function designFromEvidence(ev) {
  const layoutPattern = (ev.layoutHints || []).join(', ') || 'Standard-Startseite';
  const typography = (ev.fonts || []).join(', ') || 'System-Schriften';
  const functions = [...(ev.motionHints || [])];
  if (ev.layoutHints?.includes('Hero-Bereich')) functions.push('Hero');
  if (ev.layoutHints?.includes('Footer')) functions.push('Footer');
  return {
    name: ev.name || ev.domain,
    domain: ev.domain,
    websiteUrl: ev.websiteUrl,
    screenshotUrl: ev.screenshotUrl || null,
    palette: ev.colors?.length ? ev.colors : ['#1e293b', '#64748b'],
    layoutPattern,
    typography,
    designScore: ev.colors?.length >= 3 ? 7 : 5,
    strengths: [
      ev.layoutHints?.length ? 'Layout: ' + ev.layoutHints.join(', ') : 'Erreichbare Homepage',
      ev.motionHints?.length ? 'Effekte: ' + ev.motionHints.join(', ') : '',
    ].filter(Boolean),
    weaknesses: ev.colors?.length ? [] : ['Farben nicht eindeutig aus HTML extrahierbar'],
    designAge: ev.motionHints?.length ? 'modern' : 'mixed',
    subPages: [{ url: ev.websiteUrl, category: 'Startseite' }],
    functions,
  };
}

